"""Writes CATALOG.md: the showcase index of sources, datasets, analyses and infographics.

Generated from each item's descriptor. Do not edit by hand.
"""
from html import escape

from .analyses import load_all as load_analyses
from .config import ROOT
from .countries import select
from .datasets import load_all as load_datasets
from .infographics import load_all as load_infographics
from .sources import load_all as load_sources

HEADER = """# Catalogue and showcase

*Generated by `python -m aab catalog` from each item's descriptor. Do not edit by hand.*

This page lists everything in the repository. Start with the infographics if you want the
story, the analyses if you want the evidence, and the datasets if you want the numbers.
Status: **draft** items are being checked; **published** items are final for this version.

"""


def _figure_html(src: str, alt: str) -> str:
    return f'<img src="{src}" alt="{escape(alt, quote=True)}" width="520">'


def write_text() -> str:
    sources, datasets = load_sources(), load_datasets()
    analyses, infographics = load_analyses(), load_infographics()
    out = [HEADER]

    out.append("## Infographics\n")
    if not infographics:
        out.append("None yet.\n")
    for info in infographics.values():
        c = info.config
        rel_dir = info.path.relative_to(ROOT).as_posix()
        out.append(f"### {c['title']}\n")
        out.append(f"**Question:** {c['question']}  ")
        out.append(f"**Answer:** {c['headline']}  ")
        out.append(f"**Audience:** {'; '.join(c['audience'])}  ")
        out.append(f"**Status:** {c['status']}, version {c['version']}\n")
        out.append(_figure_html(f"{rel_dir}/outputs/infographic_en.png", c["alt_text"]) + "\n")
        links = [f"[Teacher or companion notes]({rel_dir}/README.md)" if info.notes.exists() else None]
        links += [f"[Analysis: {a}](analysis/{a}/README.md)" for a in info.analyses]
        links += [f"[Dataset: {d}](data/datasets/{d}/README.md)" for d in info.datasets]
        out.append("Sources: " + " · ".join(x for x in links if x) + "\n")

    out.append("## Analyses\n")
    for a in analyses.values():
        c = a.config
        rel_dir = a.path.relative_to(ROOT).as_posix()
        out.append(f"### {c['title']}\n")
        out.append(f"**Question:** {c['question']}  ")
        out.append(f"**Method:** `{c['method']}`  ")
        out.append(f"**Status:** {c['status']}, version {c['version']}\n")
        stem = f"{a.method}_"
        figs = sorted(p.name for p in (a.figures.glob("*.png")) if p.name.startswith(stem))
        if figs:
            out.append(_figure_html(f"{rel_dir}/outputs/figures/{figs[0]}", _alt(a)) + "\n")
        out.append(f"Read more: [findings]({rel_dir}/README.md) · [results]({rel_dir}/outputs/results.md) · "
                   f"[data behind the chart]({rel_dir}/outputs/table.csv)\n")

    out.append("## Datasets\n")
    out.append("| Dataset | Themes | Countries | Years | Indicators | Sources | Status | Version |")
    out.append("|---|---|---|---|---|---|---|---|")
    for d in datasets.values():
        c = d.config
        group = c["coverage"]["countries"]
        n = len(select(group))
        years = c["coverage"]["years"]
        srcs = ", ".join(d.source_ids)
        out.append(f"| [{c['title']}](data/datasets/{d.id}/README.md) | {', '.join(c['themes'])} | "
                   f"{n} ({group}) | {years['start']}-{years['end']} | {len(c['indicators'])} | "
                   f"{srcs} | {c['status']} | {c['version']} |")
    out.append("")

    out.append("## Sources\n")
    out.append("| Source | Producer | How the data is obtained | Licence | Known issues |")
    out.append("|---|---|---|---|---|")
    for s in sources.values():
        c = s.config
        how = "Downloaded by the pipeline" if s.access_type == "worldbank" else "Downloaded by hand, then checked"
        issues = "; ".join(s.known_issues) if s.known_issues else "None recorded"
        out.append(f"| [{c['title']}](data/sources/{s.id}/README.md) | {c.get('producer', '-')} | {how} | "
                   f"{c['licence']} | {issues} |")
    out.append("")
    return "\n".join(out)


def _alt(analysis) -> str:
    import re
    results = analysis.outputs / "results.md"
    if results.exists():
        m = re.search(r"!\[([^\]]+)\]", results.read_text(encoding="utf-8"))
        if m:
            return m.group(1)
    return analysis.config["title"]


def write() -> None:
    (ROOT / "CATALOG.md").write_text(write_text(), encoding="utf-8")
